        data = tomllib.load(f)

    pool = data.get("pool")
    if pool is None:
        raise RuntimeError("Missing [pool] table in limits.toml")

    limit_value = None
    if isinstance(pool, dict):
        if "limit" in pool:
            limit_value = pool["limit"]
        elif "connections" in pool:
            limit_value = pool["connections"]
        elif "max_connections" in pool:
            limit_value = pool["max_connections"]
    else:
        raise RuntimeError("Invalid [pool] table format")

    if limit_value is None:
        ints = [v for v in pool.values() if isinstance(v, int)]
        if len(ints) == 1:
            limit_value = ints[0]
        else:
            raise RuntimeError("Limit not found in [pool] and cannot infer from pool table")

    try:
        limit_int = int(limit_value)
    except (TypeError, ValueError):
        raise RuntimeError("Limit value is not an integer")

    print(limit_int)


if __name__ == "__main__":
