def read_limit(path="/etc/orders/limits.toml"):
    with open(path, "rb") as f:
        data = tomllib.load(f)
    pool = data.get("pool")
    if pool is None:
        raise SystemExit(2)
    if isinstance(pool, dict):
        if "limit" in pool:
            value = pool["limit"]
        elif "connections" in pool:
            value = pool["connections"]
        elif "max_connections" in pool:
            value = pool["max_connections"]
        elif "max" in pool:
            value = pool["max"]
        else:
            if len(pool) == 1:
                value = next(iter(pool.values()))
            else:
                raise SystemExit(3)
    else:
        raise SystemExit(4)
    try:
        return int(value)
    except (TypeError, ValueError):
        raise SystemExit(5)

def main():
    limit = read_limit()
    print(limit)

if __name__ == "__main__":
