{"answer":"#!/usr/bin/env python3
import tomllib

LIMIT_FILE = '/etc/orders/limits.toml'

def read_limit(path: str) -> int:
    with open(path, 'rb') as f:
        data = tomllib.load(f)
    pool = data.get('pool', {})
    for key in ('limit', 'connections', 'connection_limit', 'max_connections'):
        if key in pool and isinstance(pool[key], int):
            return pool[key]
    for v in pool.values():
        if isinstance(v, int):
            return v
    raise ValueError('No integer limit found in [pool]')


def main():
    limit = read_limit(LIMIT_FILE)
    print(int(limit))

if __name__ == '__main__':
    main()"}

